using Marina.Persistence.Data; using Microsoft.AspNetCore.Hosting; using Microsoft.AspNetCore.Mvc.Testing; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Configuration; using Microsoft.Extensions.DependencyInjection; using Microsoft.Extensions.DependencyInjection.Extensions; using Xunit;
namespace Marina.IntegrationTests;
public sealed class AuthorizationTests: IClassFixture<MarinaFactory>{private readonly HttpClient client;public AuthorizationTests(MarinaFactory factory)=>client=factory.CreateClient(new WebApplicationFactoryClientOptions{AllowAutoRedirect=false,BaseAddress=new Uri("https://localhost")});[Fact]public async Task Anonymous_user_cannot_access_admin_dashboard(){var response=await client.GetAsync("/api/v1/admin/dashboard");Assert.Equal(System.Net.HttpStatusCode.Unauthorized,response.StatusCode);}[Fact]public async Task Public_catalog_enforces_page_size_bound_and_returns_success(){var response=await client.GetAsync("/api/v1/catalog/products?pageSize=10000");response.EnsureSuccessStatusCode();var json=await response.Content.ReadAsStringAsync();Assert.Contains("\"pageSize\":50",json);}[Fact]public async Task Anonymous_user_cannot_create_return_request(){var response=await client.PostAsync($"/api/v1/returns/orders/{Guid.NewGuid()}",new StringContent("{}",System.Text.Encoding.UTF8,"application/json"));Assert.Equal(System.Net.HttpStatusCode.Unauthorized,response.StatusCode);}[Fact]public async Task Public_reviews_are_readable_and_pagination_is_bounded(){var response=await client.GetAsync($"/api/v1/catalog/products/{Guid.NewGuid()}/reviews?pageSize=999");response.EnsureSuccessStatusCode();var json=await response.Content.ReadAsStringAsync();Assert.Contains("\"pageSize\":50",json);}
[Fact]public async Task Anonymous_user_cannot_upload_product_media(){using var form=new MultipartFormDataContent();form.Add(new ByteArrayContent([0xFF,0xD8,0xFF]),"file","test.jpg");var response=await client.PostAsync($"/api/v1/admin/media/products/{Guid.NewGuid()}",form);Assert.Equal(System.Net.HttpStatusCode.Unauthorized,response.StatusCode);}
[Fact]public async Task Public_application_configuration_is_accessible(){var response=await client.GetAsync("/api/v1/app/configuration");response.EnsureSuccessStatusCode();Assert.Equal("application/json",response.Content.Headers.ContentType?.MediaType);}
[Fact]public async Task Catalog_normalizes_negative_page_number(){var response=await client.GetAsync("/api/v1/catalog/products?page=-99&pageSize=1");response.EnsureSuccessStatusCode();var json=await response.Content.ReadAsStringAsync();Assert.Contains("\"page\":1",json);}
[Fact]public async Task Missing_product_returns_not_found_without_internal_details(){var response=await client.GetAsync($"/api/v1/catalog/products/{Guid.NewGuid()}");Assert.Equal(System.Net.HttpStatusCode.NotFound,response.StatusCode);var body=await response.Content.ReadAsStringAsync();Assert.DoesNotContain("StackTrace",body,StringComparison.OrdinalIgnoreCase);}
[Fact]public async Task Authentication_endpoints_are_rate_limited(){var statuses=new List<System.Net.HttpStatusCode>();for(var i=0;i<12;i++){using var body=new StringContent("\"missing@example.com\"",System.Text.Encoding.UTF8,"application/json");var response=await client.PostAsync("/api/v1/auth/forgot-password",body);statuses.Add(response.StatusCode);}Assert.Contains(System.Net.HttpStatusCode.TooManyRequests,statuses);}
[Fact]public async Task Public_responses_include_security_headers(){var response=await client.GetAsync("/api/v1/app/configuration");response.EnsureSuccessStatusCode();Assert.Equal("nosniff",response.Headers.GetValues("X-Content-Type-Options").Single());Assert.Equal("DENY",response.Headers.GetValues("X-Frame-Options").Single());Assert.Equal("no-referrer",response.Headers.GetValues("Referrer-Policy").Single());}}
public sealed class MarinaFactory:WebApplicationFactory<Program>{public MarinaFactory()=>Environment.SetEnvironmentVariable("Jwt__Key","integration-test-signing-key-with-at-least-32-characters");protected override void ConfigureWebHost(IWebHostBuilder builder){builder.UseEnvironment("Testing");builder.ConfigureAppConfiguration((_,config)=>config.AddInMemoryCollection(new Dictionary<string,string?>{{"Jwt:Issuer","Marina.Api"},{"Jwt:Audience","Marina.App"},{"Database:ApplyMigrations","false"}}));builder.ConfigureServices(services=>{services.RemoveAll<DbContextOptions<MarinaDbContext>>();services.AddDbContext<MarinaDbContext>(o=>o.UseInMemoryDatabase($"marina-tests-{Guid.NewGuid()}"));});}}
